-- 线性表进阶：循环链表以回到起点作为遍历终止条件。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '循环链表','循环链表尾结点的 next 指向首结点；遍历应检测是否回到起点，而不是检测 null。',course.id,parent.id,'cs408-circular-linked-list','AISTU',1,'REVIEWED',7,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-linear-lists' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-circular-linked-list' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-circular-linked-list',1,'REVIEWED','循环链表',JSON_OBJECT('summary','循环链表让尾结点的 next 指回首结点；双向循环链表还让首结点的 prev 指向尾结点。因此遍历的终止条件不是遇到 null，而是指针再次回到起点。维护尾指针时可在 O(1) 找到首尾。','steps',JSON_ARRAY('尾结点 next 指向首结点形成环','双向循环时首结点 prev 指向尾结点','从首结点出发时记录起点','指针回到起点即完成一轮遍历'),'prerequisite',JSON_OBJECT('contentKey','cs408-singly-linked-list','title','单链表的结点与表示','description','先理解 next 指针如何定义逻辑顺序。'),'nextStep',JSON_OBJECT('contentKey','cs408-linked-list-reversal','title','单链表逆置','description','继续学习如何在不丢失后继的前提下反转链路。')),JSON_OBJECT('id','circular-linked-list-v1','prompt','从首结点遍历非空循环链表时，何时应停止？','options',JSON_ARRAY(JSON_OBJECT('id','RETURN_TO_START','text','当前指针再次回到起始结点'),JSON_OBJECT('id','REACH_NULL','text','当前指针变为 null')),'correctOptionId','RETURN_TO_START','correctExplanation','正确：循环链表的链接不以 null 结束，回到起点表示一轮已经完成。','incorrectExplanation','不正确：正常的非空循环链表不会沿 next 走到 null。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-circular-linked-list' AND existing.content_version=1 WHERE point.content_key='cs408-circular-linked-list' AND existing.id IS NULL;
